const listAdminAlertQueueCandidates = `-- name: ListAdminAlertQueueCandidates :many
WITH candidates AS (
 SELECT t.id AS subject_id,COALESCE(t.queued_at,t.created_at) AS cursor_time,t.status,t.queued_at,t.queued_at_source,true AS subject_exists
 FROM agent_task_queue t JOIN agent a ON a.id=t.agent_id
 JOIN organization_workspace ow ON ow.workspace_id=a.workspace_id
 WHERE ow.organization_id=$5::uuid AND t.status='queued'
 UNION ALL
 SELECT alert.subject_id,COALESCE(t.queued_at,t.created_at,alert.first_seen_at) AS cursor_time,
  COALESCE(t.status,'') AS status,t.queued_at,t.queued_at_source,
  EXISTS(SELECT 1 FROM agent_task_queue existing WHERE existing.id=alert.subject_id) AS subject_exists
 FROM admin_alert alert LEFT JOIN agent_task_queue t ON t.id=alert.subject_id
  AND EXISTS(SELECT 1 FROM agent a JOIN organization_workspace ow ON ow.workspace_id=a.workspace_id
   WHERE a.id=t.agent_id AND ow.organization_id=alert.organization_id)
 WHERE alert.organization_id=$5::uuid AND alert.rule='queue_timeout'
  AND alert.condition_active AND t.status IS DISTINCT FROM 'queued'
)
SELECT subject_id, cursor_time, status, queued_at, queued_at_source, subject_exists FROM candidates WHERE cursor_time<=$1::timestamptz
 AND ($2::timestamptz IS NULL OR (cursor_time,subject_id)>($2,$3::uuid))
ORDER BY cursor_time,subject_id LIMIT $4::int
`

type ListAdminAlertQueueCandidatesParams struct {
	ObservedAt     pgtype.Timestamptz `json:"observed_at"`
	CursorTime     pgtype.Timestamptz `json:"cursor_time"`
	CursorID       pgtype.UUID        `json:"cursor_id"`
	BatchLimit     int32              `json:"batch_limit"`
	OrganizationID pgtype.UUID        `json:"organization_id"`
}

type ListAdminAlertQueueCandidatesRow struct {
	SubjectID      pgtype.UUID        `json:"subject_id"`
	CursorTime     pgtype.Timestamptz `json:"cursor_time"`
	Status         string             `json:"status"`
	QueuedAt       pgtype.Timestamptz `json:"queued_at"`
	QueuedAtSource pgtype.Text        `json:"queued_at_source"`
	SubjectExists  bool               `json:"subject_exists"`
}

func (q *Queries) ListAdminAlertQueueCandidates(ctx context.Context, arg ListAdminAlertQueueCandidatesParams) ([]ListAdminAlertQueueCandidatesRow, error) {
	rows, err := q.db.Query(ctx, listAdminAlertQueueCandidates,
		arg.ObservedAt,
		arg.CursorTime,
		arg.CursorID,
		arg.BatchLimit,
		arg.OrganizationID,
	)
	if err != nil {
		return nil, err
	}
	defer rows.Close()
	items := []ListAdminAlertQueueCandidatesRow{}
	for rows.Next() {
		var i ListAdminAlertQueueCandidatesRow
		if err := rows.Scan(
			&i.SubjectID,
			&i.CursorTime,
			&i.Status,
			&i.QueuedAt,
			&i.QueuedAtSource,
			&i.SubjectExists,
		); err != nil {
			return nil, err
		}
		items = append(items, i)
	}
	if err := rows.Err(); err != nil {
		return nil, err
	}
	return items, nil
}

const listAdminAlerts = `-- name: ListAdminAlerts :many
SELECT id, organization_id, rule, subject_kind, subject_id, fingerprint, severity, status, condition_active, first_seen_at, last_seen_at, last_observed_at, occurrence_count, assignee_id, acknowledged_at, resolved_at, closed_at, resolution_code, related_task_id, version, operation_id, created_at, updated_at FROM admin_alert WHERE organization_id=$1::uuid
 AND first_seen_at<=$2::timestamptz
 AND ($3::timestamptz IS NULL OR first_seen_at>=$3)
 AND first_seen_at<$4::timestamptz
 AND ($5::text='all' OR status=$5
  OR ($5='active' AND status IN ('open','acknowledged')))
 AND ($6::text='' OR rule=$6)
 AND ($7::text='' OR severity=$7)
 AND ($8::text='' OR subject_kind=$8)
 AND ($9::uuid IS NULL OR subject_id=$9)
 AND ($10::uuid IS NULL OR assignee_id=$10)
 AND ($11::text='' OR id::text ILIKE '%'||$11||'%'
  OR subject_id::text ILIKE '%'||$11||'%')
 AND ($12::timestamptz IS NULL OR (first_seen_at,id)<($12,$13::uuid))
ORDER BY first_seen_at DESC,id DESC LIMIT $14::int
`

